std::vector<std::int8_t> gen_chunk(long seed, int cx, int cz) {
  craftpp::world::ChunkManager mgr(seed);
  craftpp::world::TerrainProvider prov(mgr, seed);
  prov.set_chunk_seed(cx, cz);
  std::vector<std::int8_t> blocks;
  prov.generate_terrain(cx, cz, blocks);
  prov.replace_biome_blocks(cx, cz, blocks, mgr.block_biomes(cx * 16, cz * 16, 16, 16));
  return blocks;
}
std::vector<int> heightmap(const std::vector<std::int8_t>& b) {
  std::vector<int> hm;
  for (int x = 0; x < 16; x++) for (int z = 0; z < 16; z++) {
    int top = -1;
    for (int y = 127; y >= 0; y--)
      if (b[static_cast<std::size_t>((x * 16 + z) * 128 + y)] != 0) { top = y; break; }
    hm.push_back(top);
  }
  return hm;
}
// mirrors java.util.Arrays.hashCode(byte[]): h = 31*h + v, 32-bit wrap
std::int32_t array_hash(const std::vector<std::int8_t>& b) {
  std::uint32_t h = 1;
  for (std::int8_t v : b) h = 31 * h + static_cast<std::uint32_t>(static_cast<std::int32_t>(v));
  return static_cast<std::int32_t>(h);
}
